const $ = (s,root=document)=>root.querySelector(s);
const esc = x => String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',cards:'<rect x="6" y="5" width="14" height="16" rx="2"/><path d="M3 17V3h13M10 10h6m-6 4h4"/>',notes:'<path d="M14 3H5v18h14V8zm0 0v5h5M8 12h8m-8 4h6"/>',book:'<path d="M12 5v16M3 3c4 0 7 0 9 2 2-2 5-2 9-2v16c-4 0-7 0-9 2-2-2-5-2-9-2z"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',back:'<path d="M19 12H5m5-5-5 5 5 5"/>',check:'<path d="m5 12 4 4 10-10"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4z"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',play:'<path d="m8 4 12 8-12 8z"/>',pause:'<path d="M8 4v16M16 4v16"/>',reset:'<path d="M4 9a8 8 0 1 1 0 6M4 3v6h6"/>',next:'<path d="m8 5 7 7-7 7M19 5v14"/>',prev:'<path d="m16 5-7 7 7 7M5 5v14"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>',code:'<path d="m8 7-5 5 5 5m8-10 5 5-5 5M14 4l-4 16"/>',chart:'<path d="M4 4v16h17M8 16v-4m5 4V8m5 8V5"/>',list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h1m-1 6h1m-1 6h1"/>',branch:'<circle cx="6" cy="5" r="2"/><circle cx="18" cy="8" r="2"/><circle cx="6" cy="19" r="2"/><path d="M6 7v10m0-3h7c4 0 5-2 5-4"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.grid}</svg>`;
const categories=['1D DP','Grid DP','Subsequences','Strings','Stocks','LIS','Partition DP','Rectangles'];
const categoryIcons=['branch','grid','list','code','chart','chart','branch','grid'];
const categoryHints=['Build the foundation','Move through states','Pick, skip, repeat','Compare two prefixes','Decisions over time','Find the longest chain','Choose the best split','Think in areas'];
const data=window.CURRICULUM;
let localError=false;
let saved={done:[],bookmarks:[],notes:{},reviews:{},last:2};
try{const s=JSON.parse(localStorage.getItem('dp-studio-v1')||'null');if(s&&typeof s==='object'){saved.done=Array.isArray(s.done)?s.done.filter(Number.isInteger):[];saved.bookmarks=Array.isArray(s.bookmarks)?s.bookmarks.filter(Number.isInteger):[];saved.notes=s.notes&&typeof s.notes==='object'&&!Array.isArray(s.notes)?s.notes:{};saved.reviews=s.reviews&&typeof s.reviews==='object'&&!Array.isArray(s.reviews)?s.reviews:{};saved.last=Number.isInteger(s.last)?s.last:2;}}catch{localError=true;}
let category='All',search='',status='all',difficulty='all',lessonTab='learn',approach=1,step=0,playing=false,timer=null,speed=1000,flashIndex=0,flipped=false,flashMode='all',menuOpen=false;
function persist(){try{localStorage.setItem('dp-studio-v1',JSON.stringify(saved));localError=false;return true;}catch{localError=true;toast('Browser storage is unavailable. Export a backup to keep your work.');return false;}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),2600);}
function route(){const parts=location.hash.slice(1).split('/');return {page:parts[0]||'library',id:Number(parts[1])};}
function go(page){location.hash=page;}
function stop(){playing=false;clearInterval(timer);timer=null;}
function done(id){saved.done=saved.done.includes(id)?saved.done.filter(x=>x!==id):[...saved.done,id];persist();render();}
function bookmark(id){saved.bookmarks=saved.bookmarks.includes(id)?saved.bookmarks.filter(x=>x!==id):[...saved.bookmarks,id];persist();render();}
function render(){const r=route();const p=data.find(p=>p.id===r.id);const page=r.page;const active=page==='lesson'?'library':page;$('#app').innerHTML=`<div class="shell"><aside class="sidebar ${menuOpen?'open':''}"><a href="#library" class="brand"><span class="brand-mark">${icon('branch')}</span><span>dp studio<small>ONE PATTERN AT A TIME</small></span></a><nav class="nav-group" aria-label="Main navigation">${[['library','grid','Problem library'],['flashcards','cards','Flashcards'],['notes','notes','My notes'],['saved','bookmark','Saved for later']].map(([id,i,label])=>`<button class="nav-item ${active===id?'active':''}" data-go="${id}">${icon(i)}${label}${id==='flashcards'?`<span class="count">${data.length*2}</span>`:''}</button>`).join('')}</nav><div><div class="nav-label">DYNAMIC PROGRAMMING</div><nav class="category-nav" aria-label="DP categories">${categories.map((c,i)=>`<button data-category="${c}" class="${category===c?'active':''}">${c}<span>${data.filter(p=>p.category===c).length}</span></button>`).join('')}</nav></div><div class="side-bottom"><div class="storage"><strong>${icon('lock')} Your own learning space</strong>Notes & progress saved in this browser. No API keys needed.</div></div></aside><div class="workspace"><header class="topbar"><button class="mobile-menu" aria-label="Toggle navigation" data-action="menu">${icon('menu')}</button><div class="breadcrumb">Your workspace <b>/ &nbsp; ${page==='lesson'?'Dynamic Programming':({flashcards:'Flashcards',notes:'My notes',saved:'Saved for later'}[page]||'Dynamic Programming')}</b></div><div class="topright"><span class="pill">Python edition</span><span class="avatar" title="Local learner">You</span></div></header><main class="main fade">${localError?'<div class="notice">Local storage is unavailable. Changes last only for this session. Export a backup from My notes.</div>':''}${page==='lesson'?(p?lesson(p):'<div class="empty">This lesson does not exist.<br><a href="#library">Back to library</a></div>'):page==='flashcards'?flashcards():page==='notes'?notes():library(page==='saved')}</main></div></div>`;bind();if(page==='lesson'&&p)bindLesson(p);if(page==='flashcards')bindFlash();}
function library(onlySaved=false){const complete=data.filter(p=>saved.done.includes(p.id)).length;const last=data.find(p=>p.id===saved.last)||data[1]||data[0];const percent=Math.round(complete/data.length*100);return `<div class="page-heading"><div><div class="eyebrow">STRIVER'S A2Z · DYNAMIC PROGRAMMING</div><h1>${onlySaved?'Saved for a second look.':'Learn the pattern. Solve the problem.'}</h1><p>${onlySaved?'Your bookmarked problems, ready when you are.':'Build your intuition, one small state at a time.'}</p></div><button class="btn" data-go="flashcards">${icon('cards')} Quick revision</button></div>${onlySaved?'':`<div class="hero-grid"><section class="continue-card"><div class="eyebrow">${icon('book')} ${saved.done.length?'CONTINUE YOUR JOURNEY':'YOUR NEXT SMALL STEP'}</div><h2>${esc(last.title)}</h2><p>${esc(last.pattern)}. Explore the intuition, then watch the solution unfold.</p><button class="btn lime" data-go="lesson/${last.id}">${saved.done.length?'Continue learning':'Explore lesson'} ${icon('arrow')}</button><div class="mini-path" aria-hidden="true">${[1,2,3,5].map((v,i)=>`<div class="mini-step" style="height:${40+i*18}px">${v}</div>`).join('')}</div></section><section class="progress-card"><div class="progress-title">Your learning progress ${icon('chart')}</div><div class="progress-middle"><div><div class="progress-number">${complete} <small>/ ${data.length}</small></div><div class="progress-caption">lessons completed</div></div><div class="ring" style="--percent:${percent}%"><span>${percent}%</span></div></div><div class="stats-inline"><span><b>${Object.keys(saved.notes).filter(k=>typeof saved.notes[k]==='string'&&saved.notes[k].trim()).length}</b> personal notes</span><span><b>${Object.values(saved.reviews).filter(v=>v==='known').length}</b> cards remembered</span></div></section></div><div class="section-heading"><h2>Explore by pattern</h2><span>${categories.length} categories · a connected learning path</span></div><div class="category-cards">${categories.map((c,i)=>{const total=data.filter(p=>p.category===c).length;const count=data.filter(p=>p.category===c&&saved.done.includes(p.id)).length;return `<button class="category-card ${category===c?'active':''}" data-category="${c}"><span class="category-icon">${icon(categoryIcons[i])}</span><strong>${c}</strong><small>${categoryHints[i]}</small><div class="thin-progress"><i style="width:${count/total*100}%"></i></div></button>`}).join('')}</div>`}<div class="section-heading"><h2>${category==='All'?'Your problem library':category} <span id="result-count"></span></h2>${category!=='All'?'<button class="back" data-category="All">Show all patterns</button>':'<span>Understand → practice → remember</span>'}</div><section class="problem-panel"><div class="table-tools"><label class="search">${icon('search')}<input id="search" aria-label="Search problems" placeholder="Search a problem or pattern…" value="${esc(search)}"></label><div class="filter-row"><select id="difficulty" aria-label="Filter difficulty">${['all','Easy','Medium','Hard'].map(v=>`<option value="${v}" ${difficulty===v?'selected':''}>${v==='all'?'All difficulties':v}</option>`).join('')}</select><select id="status" aria-label="Filter progress">${[['all','All progress'],['todo','To learn'],['done','Completed']].map(([v,l])=>`<option value="${v}" ${status===v?'selected':''}>${l}</option>`).join('')}</select></div></div><div class="table-head"><span></span><span>PROBLEM</span><span>PATTERN</span><span>LEVEL</span><span>SAVE</span></div><div id="rows">${rows(onlySaved)}</div><div class="table-footer"><span>Original explanations · Python 3.9+ · Local progress</span><a class="source-link" href="https://takeuforward.org/dsa/strivers-a2z-sheet-learn-dsa-a-to-z" target="_blank" rel="noopener">Based on Striver's A2Z ↗</a></div></section><p style="font-size:11px;color:#95a08c;margin-top:16px">56 learning units cover the 55-problem DP curriculum, including a dedicated matrix-chain tabulation workshop. Independent learning companion; not affiliated with takeUforward.</p>`;}
function filtered(onlySaved=false){return data.filter(p=>(!onlySaved||saved.bookmarks.includes(p.id))&&(category==='All'||p.category===category)&&(difficulty==='all'||p.difficulty===difficulty)&&(status==='all'||((status==='done')===saved.done.includes(p.id)))&&(`${p.title} ${p.pattern} ${p.category}`.toLowerCase().includes(search.toLowerCase())));}
function rows(onlySaved){const list=filtered(onlySaved);return list.length?list.map(p=>`<div class="problem-row"><button class="check ${saved.done.includes(p.id)?'done':''}" data-done="${p.id}" aria-label="${saved.done.includes(p.id)?'Mark incomplete':'Mark complete'}: ${esc(p.title)}" aria-pressed="${saved.done.includes(p.id)}">${saved.done.includes(p.id)?icon('check'):''}</button><button class="problem-link" data-go="lesson/${p.id}">${esc(p.title)}<small>DP ${String(p.id).padStart(2,'0')} &nbsp;·&nbsp; ${esc(p.pattern)}</small></button><span class="tag">${p.category}</span><span class="difficulty ${p.difficulty}">${p.difficulty}</span><button class="bookmark ${saved.bookmarks.includes(p.id)?'saved':''}" data-bookmark="${p.id}" aria-label="Bookmark ${esc(p.title)}" aria-pressed="${saved.bookmarks.includes(p.id)}">${icon('bookmark')}</button></div>`).join(''):`<div class="empty">${onlySaved?'No saved problems match. Use a bookmark in the library to keep one here.':'No problems match these filters.'}<br><button class="btn" data-action="clear-filters">Clear filters</button></div>`;}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{menuOpen=false;go(b.dataset.go)});document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;menuOpen=false;if(route().page!=='library')go('library');else render()});document.querySelectorAll('[data-done]').forEach(b=>b.onclick=()=>done(+b.dataset.done));document.querySelectorAll('[data-bookmark]').forEach(b=>b.onclick=()=>bookmark(+b.dataset.bookmark));document.querySelectorAll('[data-action="clear-filters"]').forEach(b=>b.onclick=()=>{search='';status=difficulty='all';category='All';render()});$('[data-action="menu"]')?.addEventListener('click',()=>{menuOpen=!menuOpen;$('.sidebar').classList.toggle('open',menuOpen)});const update=()=>{$('#rows').innerHTML=rows(route().page==='saved');bindRows();};$('#search')?.addEventListener('input',e=>{search=e.target.value;update()});$('#status')?.addEventListener('change',e=>{status=e.target.value;update()});$('#difficulty')?.addEventListener('change',e=>{difficulty=e.target.value;update()});$('[data-action="export"]')?.addEventListener('click',exportData);$('#import')?.addEventListener('change',importData);}
function bindRows(){document.querySelectorAll('#rows [data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('#rows [data-done]').forEach(b=>b.onclick=()=>done(+b.dataset.done));document.querySelectorAll('#rows [data-bookmark]').forEach(b=>b.onclick=()=>bookmark(+b.dataset.bookmark));document.querySelectorAll('#rows [data-action="clear-filters"]').forEach(b=>b.onclick=()=>{search='';status=difficulty='all';category='All';render()});}
function lesson(p){return `<div class="lesson-top"><button class="back" data-go="library">${icon('back')} Back to library</button><button class="btn ${saved.done.includes(p.id)?'':'primary'}" data-done="${p.id}">${icon('check')} ${saved.done.includes(p.id)?'Completed':'Mark complete'}</button></div><div class="eyebrow">${p.category} &nbsp; / &nbsp; DP ${String(p.id).padStart(2,'0')}</div><div class="lesson-heading"><h1>${esc(p.title)}</h1><span class="difficulty ${p.difficulty}">${p.difficulty}</span><button class="bookmark ${saved.bookmarks.includes(p.id)?'saved':''}" data-bookmark="${p.id}" aria-label="Bookmark lesson">${icon('bookmark')}</button></div><div class="lesson-meta"><span>${esc(p.pattern)}</span><span>·</span><span>Python 3.9+</span></div><div class="lesson-layout"><div><section class="card"><div class="tabs" role="tablist" aria-label="Lesson sections">${[['learn','Understand'],['code','Python solutions'],['patterns','Pattern notes'],['notes','My notes']].map(([id,label])=>`<button role="tab" aria-selected="${lessonTab===id}" data-tab="${id}" class="${lessonTab===id?'active':''}">${label}</button>`).join('')}</div><div id="lesson-content">${lessonContent(p)}</div></section><div class="lesson-top"><button class="back" ${p.id===1?'disabled':''} data-go="lesson/${p.id-1}">${icon('back')} Previous lesson</button><button class="back" ${!data.some(x=>x.id===p.id+1)?'disabled':''} data-go="lesson/${p.id+1}">Next lesson ${icon('arrow')}</button></div></div><aside class="visualizer"><section class="card"><div class="visual-heading"><h3>Make the states click.</h3><span class="live-tag">INTERACTIVE DRY RUN</span></div><div class="subtitle">Memoization · resolved states in dependency order</div><div class="subtitle">${esc(Object.entries(p.example).map(([k,v])=>`${k} = ${JSON.stringify(v)}`).join(' · '))}</div><div id="visual">${visual(p)}</div><div class="play-controls"><button data-action="reset" aria-label="Reset animation">${icon('reset')}</button><button data-action="prev" aria-label="Previous step">${icon('prev')}</button><button class="play" data-action="play">${icon(playing?'pause':'play')} ${playing?'Pause':'Play'}</button><button data-action="next" aria-label="Next step">${icon('next')}</button><select id="speed" aria-label="Animation speed">${[[1500,'0.5×'],[1000,'1×'],[500,'2×']].map(([v,t])=>`<option value="${v}" ${v===speed?'selected':''}>${t}</option>`).join('')}</select></div><input class="scrubber" id="scrubber" aria-label="Dry run step" type="range" min="0" max="${p.trace.length-1}" value="${step}"><div class="legend"><span><i></i>Current state</span><span><i class="purple"></i>Dependencies</span></div></section><section class="card"><div class="eyebrow">THE STATE TO REMEMBER</div><p style="font-size:14px;margin:0">${esc(p.stateMeaning)}</p><div class="callout" style="margin-bottom:0">${esc(p.notes[0])}</div></section></aside></div>`;}
function lessonContent(p){if(lessonTab==='notes')return `<h3>Your thinking, in your words.</h3><p class="notes-tip">What made this click? Write down the state, a mistake to avoid, or a variation to try.</p><textarea class="notes-input" id="note" aria-label="Personal notes for ${esc(p.title)}" placeholder="My intuition…\n\nThe recurrence…\n\nRemember to…">${esc(typeof saved.notes[p.id]==='string'?saved.notes[p.id]:'')}</textarea><div class="notes-status" id="note-status">${localError?'Session only — export a backup.':'Saved automatically in this browser.'}</div>`;
if(lessonTab==='patterns')return `<div class="lesson-copy"><h3>How to recognize this pattern</h3><p>${esc(p.intuition[0])}</p><div class="callout"><strong>${esc(p.pattern)}</strong><br>${esc(p.stateMeaning)}</div><h3>Keep these in your toolkit</h3><ul class="pattern-list">${p.notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul><h3>Memory prompt</h3><p>Without looking at the code, explain what one state means, which smaller states it needs, and why the base cases are correct.</p><button class="btn" data-go="flashcards">${icon('cards')} Practice with flashcards</button></div>`;
if(lessonTab==='code'){const labels=['Recursion','Memoization','Tabulation','Space optimized'];const descriptions=[`Start with the mathematical recurrence. Each recursive call answers a smaller instance. This intentionally repeats work so you can see where memoization helps.`,`The recurrence stays the same. @cache stores answers by the state arguments, so each distinct state is evaluated once. Inputs are captured by the function; only hashable indices enter the cache.`,`Evaluate states in dependency order. The dictionary dp is an explicit table keyed by state. value handles boundaries and reads already-computed answers; transition computes exactly one cell. This representation makes multidimensional states easy to inspect.`,p.opt_note];return `<div class="approach-tabs" role="tablist" aria-label="Solution approach">${labels.map((l,i)=>`<button role="tab" aria-selected="${i===approach}" data-approach="${i}" class="${i===approach?'active':''}">${l}</button>`).join('')}</div><div class="lesson-copy"><h3>${labels[approach]}</h3><p>${esc(descriptions[approach])}</p></div><div class="code-wrap"><div class="code-head"><span>PYTHON 3.9+ &nbsp; / &nbsp; ${labels[approach].toUpperCase()}</span><button id="copy">Copy code</button></div><pre><code>${highlight(p.codes[approach])}</code></pre></div><div class="complexity"><div>TIME<strong>${esc(approach===0?p.rec_time:approach===3?p.optTime:p.time)}</strong></div><div>AUXILIARY SPACE<strong>${esc(approach===0?p.rec_space:approach===3?p.optSpace:p.space)}</strong></div></div><p style="font-size:12px">${esc(approach===3?p.opt_note:approach===1?'Memoization also uses the recursion stack: '+p.rec_space+'. Avoid deep recursion for large inputs; use the iterative version.':'Bounds count arithmetic and comparison operations. Code uses solve(…) with the inputs shown in the example.')}</p>${p.extra?`<div class="callout">${esc(p.extra)}</div>`:''}<div class="example"><span>Try it</span><br>solve(${esc(Object.entries(p.example).map(([k,v])=>`${k}=${JSON.stringify(v)}`).join(', '))})<br><span>Returns</span> ${esc(JSON.stringify(p.expected))}</div>`;}
return `<div class="lesson-copy"><h3>The problem</h3><p>${esc(p.statement)}</p><div class="example">${Object.entries(p.example).map(([k,v])=>`<span>${esc(k)}</span> = ${esc(JSON.stringify(v))}`).join('<br>')}<br><span>Output</span> = ${esc(JSON.stringify(p.expected))}</div><h3>Think about the final choice.</h3>${p.intuition.map((t,i)=>`<p><strong style="color:#526c3b">0${i+1}.</strong> ${esc(t)}</p>`).join('')}<div class="callout"><strong>Define your state</strong><br>${esc(p.stateMeaning)}</div><h3>The recurrence</h3><div class="code-wrap"><pre><code>${highlight(p.recurrence)}</code></pre></div><h3>Why the boundary works</h3><pre class="example">${highlight(p.state)}</pre><h3>From an idea to an efficient solution</h3><p>Write the recurrence → cache repeated states → fill the table in dependency order → keep only the values the next state needs.</p><button class="btn primary" data-tab="code">Explore the Python solutions ${icon('arrow')}</button></div>`;}
function highlight(s){return s.split(/("[^"\n]*"|'[^'\n]*'|#[^\n]*|\b(?:def|return|if|else|elif|for|in|range|from|import|while|and|or|not|True|False|None|break|continue)\b|\b\d+\b)/g).map(t=>{const e=esc(t);return /^#/.test(t)?`<span class="comment">${e}</span>`:/^["']/.test(t)?`<span class="str">${e}</span>`:/^\d+$/.test(t)?`<span class="num">${e}</span>`:/^(def|return|if|else|elif|for|in|range|from|import|while|and|or|not|True|False|None|break|continue)$/.test(t)?`<span class="kw">${e}</span>`:e;}).join('');}
function stateTable(p,event){
  if(p.stateNames.length!==2)return '';
  const entries=p.trace.filter(e=>e.key.every(k=>Number.isInteger(k)&&k>=0));
  if(!entries.length)return '';
  const maxR=Math.max(...entries.map(e=>e.key[0])),maxC=Math.max(...entries.map(e=>e.key[1]));
  if(maxR>15||maxC>20)return '';
  const rows=maxR+1,cols=maxC+1;
  const known=p.trace.slice(0,step+1);
  let out='<div class="dp-table-wrap"><div class="table-caption">STATE TABLE <span>'+esc(p.stateNames[0])+' ↓ &nbsp; '+esc(p.stateNames[1])+' →</span></div><div class="dp-table" style="grid-template-columns:25px repeat('+cols+',minmax(30px,1fr))"><div></div>';
  for(let c=0;c<cols;c++)out+='<div class="axis">'+c+'</div>';
  for(let r=0;r<rows;r++){
    out+='<div class="axis">'+r+'</div>';
    for(let c=0;c<cols;c++){
      const e=known.find(e=>e.key[0]===r&&e.key[1]===c);
      const active=event.key[0]===r&&event.key[1]===c;
      const dep=event.deps.some(d=>d.key[0]===r&&d.key[1]===c);
      out+='<div class="dp-cell '+(active?'active':dep?'dep':e?'resolved':'')+'" title="'+esc('f('+r+', '+c+')'+(e?' = '+val(e.value):': not yet evaluated'))+'">'+(e?esc(typeof e.value==='string'&&e.value.length>4?e.value.slice(0,3)+'…':val(e.value)):'·')+'</div>';
    }
  }
  return out+'</div><small>Only states visited by this example are filled.</small></div>';
}
const val=v=>Array.isArray(v)?`(${v.join(', ')})`:typeof v==='boolean'?(v?'True':'False'):String(v);
const stateLabel=(p,key)=>`f(${key.map(val).join(', ')})`;
function visual(p){step=Math.max(0,Math.min(step,p.trace.length-1));const event=p.trace[step];if(!event)return '<p>No trace available.</p>';const deps=event.deps.filter((d,i,a)=>a.findIndex(x=>JSON.stringify(x.key)===JSON.stringify(d.key))===i);const simple=p.stateNames.length===1&&p.trace.every(e=>e.key.length===1&&Number.isInteger(e.key[0]))&&p.trace.length<18;let nodes='';if(simple){const sorted=[...p.trace].sort((a,b)=>a.key[0]-b.key[0]);nodes=`<div class="state-track">${sorted.map(e=>{const index=p.trace.indexOf(e);const current=index===step;const dep=deps.some(d=>JSON.stringify(d.key)===JSON.stringify(e.key));return `<div class="state-node ${current?'current':dep?'dependency':index>step?'future':''}">${index<=step?esc(val(e.value)):'?'}<small>${esc(stateLabel(p,e.key))}</small></div>`}).join('')}</div>`;}else{nodes=`<div class="state-track">${deps.length?deps.map(d=>`<div class="state-node dependency">${esc(val(d.value))}<small>${esc(stateLabel(p,d.key))}</small></div>`).join(''):'<span class="state-label">A base case: no smaller state needed</span>'}</div><div class="dependency-arrow">↓</div><div class="active-state"><span class="state-label">${esc(stateLabel(p,event.key))}</span><strong>${esc(val(event.value))}</strong></div>`;}return `${stateTable(p,event)}<div class="visual-stage">${nodes}${simple?`<div class="state-label">${esc(stateLabel(p,event.key))} = <strong>${esc(val(event.value))}</strong></div>`:''}</div><div class="step-text"><strong>Step ${step+1} of ${p.trace.length} · ${deps.length?'Combine smaller answers':'Establish a base case'}</strong><br>${esc(stateLabel(p,event.key))} ${deps.length?`reads ${deps.map(d=>`${esc(stateLabel(p,d.key))} = ${esc(val(d.value))}`).join(', ')}.`:'is resolved directly by the boundary rule.'} Store <strong>${esc(val(event.value))}</strong>.${step===p.trace.length-1?`<br>Final answer after the return expression: <strong>${esc(val(p.expected))}</strong>.`:''}</div>`;}
function bindLesson(p){document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{lessonTab=b.dataset.tab;render()});document.querySelectorAll('[data-approach]').forEach(b=>b.onclick=()=>{approach=+b.dataset.approach;render()});$('#copy')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(p.codes[approach]);toast('Python code copied');}catch{toast('Clipboard unavailable. Select and copy the code.');}});$('#note')?.addEventListener('input',e=>{saved.notes[p.id]=e.target.value;const ok=persist();$('#note-status').textContent=ok?'Saved just now · only in this browser':'Session only — export a backup.';});const update=()=>{$('#visual').innerHTML=visual(p);$('#scrubber').value=step;const b=$('[data-action="play"]');b.innerHTML=`${icon(playing?'pause':'play')} ${playing?'Pause':'Play'}`;};$('[data-action="reset"]').onclick=()=>{stop();step=0;update()};$('[data-action="prev"]').onclick=()=>{stop();step=Math.max(0,step-1);update()};$('[data-action="next"]').onclick=()=>{stop();step=Math.min(p.trace.length-1,step+1);update()};const start=()=>{playing=true;clearInterval(timer);timer=setInterval(()=>{if(route().page!=='lesson'){stop();return}step++;if(step>=p.trace.length-1){step=p.trace.length-1;stop()}update()},speed);update();};$('[data-action="play"]').onclick=()=>{if(playing){stop();update()}else{if(step===p.trace.length-1)step=0;start()}};$('#speed').onchange=e=>{speed=+e.target.value;if(playing)start()};$('#scrubber').oninput=e=>{stop();step=+e.target.value;update()};}
function deck(){let all=data.filter(p=>category==='All'||p.category===category).flatMap(p=>[{id:p.id+'-state',p,q:`What is the state for ${p.title}?`,a:p.stateMeaning},{id:p.id+'-pattern',p,q:`${p.title}: what is the key insight?`,a:p.intuition[0]+' '+p.notes[0]}]);if(flashMode==='review')all=all.filter(c=>saved.reviews[c.id]!=='known');return all;}
function flashcards(){const cards=deck();flashIndex=Math.max(0,Math.min(flashIndex,cards.length-1));const c=cards[flashIndex];return `<div class="page-heading"><div><div class="eyebrow">ACTIVE RECALL</div><h1>A little recall. A lasting pattern.</h1><p>Say the answer out loud before turning the card.</p></div></div><div class="filter-row"><select id="flash-category" aria-label="Flashcard category">${['All',...categories].map(v=>`<option ${category===v?'selected':''}>${v}</option>`).join('')}</select><select id="flash-mode" aria-label="Flashcard review mode"><option value="all" ${flashMode==='all'?'selected':''}>All cards</option><option value="review" ${flashMode==='review'?'selected':''}>Needs practice</option></select></div><div class="flash-layout">${c?`<div class="flash-count">${esc(c.p.category)} &nbsp;·&nbsp; Card ${flashIndex+1} of ${cards.length}</div><button class="flash-card ${flipped?'flipped':''}" id="flip" aria-label="${flipped?'Show question':'Reveal answer'}"><span class="eyebrow">${flipped?'THE CONNECTION':'FIND THE PATTERN'}</span>${flipped?`<p>${esc(c.a)}</p>`:`<h2>${esc(c.q)}</h2>`}<small>${flipped?'Click to return to the question':'Click to reveal · or press Space'}</small></button><div class="flash-controls"><button class="btn" aria-label="Previous flashcard" data-flash="prev" ${flashIndex===0?'disabled':''}>${icon('back')}</button>${flipped?'<button class="btn" data-flash="again">Practice again</button><button class="btn primary" data-flash="known">'+icon('check')+' Got it</button>':'<button class="btn primary" id="reveal">Reveal answer</button>'}<button class="btn" aria-label="Next flashcard" data-flash="next" ${flashIndex===cards.length-1?'disabled':''}>${icon('arrow')}</button></div><div class="flash-count"><button class="back" style="display:inline-flex" data-go="lesson/${c.p.id}">Revisit ${esc(c.p.title)} ${icon('arrow')}</button></div>`:'<div class="empty">You remembered every card in this selection.<br>Choose All cards to revise them again.</div>'}</div>`;}
function bindFlash(){$('#flip')?.addEventListener('click',()=>{flipped=!flipped;render()});$('#reveal')?.addEventListener('click',()=>{flipped=true;render()});$('#flash-category').onchange=e=>{category=e.target.value;flashIndex=0;flipped=false;render()};$('#flash-mode').onchange=e=>{flashMode=e.target.value;flashIndex=0;flipped=false;render()};document.querySelectorAll('[data-flash]').forEach(b=>b.onclick=()=>{const cards=deck(),c=cards[flashIndex];const action=b.dataset.flash;if(action==='prev')flashIndex--;else if(action==='next')flashIndex++;else{saved.reviews[c.id]=action;persist();if(!(action==='known'&&flashMode==='review'))flashIndex=(flashIndex+1)%cards.length;toast(action==='known'?'Remembered. Nice connection.':'Saved for more practice.');}flipped=false;render()});}
function notes(){const list=data.filter(p=>typeof saved.notes[p.id]==='string'&&saved.notes[p.id].trim());return `<div class="page-heading"><div><div class="eyebrow">YOUR PERSONAL PLAYBOOK</div><h1>Keep what makes it click.</h1><p>${list.length} ${list.length===1?'lesson':'lessons'} with personal notes, saved on this device.</p></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn" data-action="export">${icon('download')} Export backup</button><label class="btn" style="cursor:pointer">Import backup<input type="file" id="import" accept="application/json,.json" hidden></label></div></div>${list.length?list.map(p=>`<button class="card note-card" style="display:block;width:100%;text-align:left" data-go="lesson/${p.id}"><div class="eyebrow">${p.category}</div><h3>${esc(p.title)}</h3><p>${esc(saved.notes[p.id])}</p><span class="back">Open lesson ${icon('arrow')}</span></button>`).join(''):'<div class="card empty">Your notebook starts with one insight.<br>Open any lesson and select <strong>My notes</strong> to write it down.<br><br><button class="btn primary" data-go="library">Explore the library '+icon('arrow')+'</button></div>'}<p style="font-size:13px">Backups include notes, completed lessons, bookmarks, and flashcard ratings. Import merges with this browser; your existing notes are kept when both copies have a note.</p>`;}
function exportData(){const blob=new Blob([JSON.stringify({version:1,...saved},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='dp-studio-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exported');}
async function importData(e){try{const file=e.target.files[0];if(!file)return;if(file.size>5000000)throw Error();const x=JSON.parse(await file.text());const ids=new Set(data.map(p=>p.id));const validIds=v=>Array.isArray(v)&&v.every(id=>Number.isInteger(id)&&ids.has(id));const validNotes=x.notes&&typeof x.notes==='object'&&!Array.isArray(x.notes)&&Object.entries(x.notes).every(([k,v])=>ids.has(Number(k))&&typeof v==='string');const validReviews=x.reviews&&typeof x.reviews==='object'&&!Array.isArray(x.reviews)&&Object.entries(x.reviews).every(([k,v])=>/^\d+-(state|pattern)$/.test(k)&&ids.has(Number(k.split('-')[0]))&&['known','again'].includes(v));if(x.version!==1||!validIds(x.done)||!validIds(x.bookmarks)||!validNotes||!validReviews)throw Error();saved.done=[...new Set([...saved.done,...x.done])];saved.bookmarks=[...new Set([...saved.bookmarks,...x.bookmarks])];saved.notes={...x.notes,...saved.notes};saved.reviews={...x.reviews,...saved.reviews};persist();render();toast('Backup merged. Your existing notes were kept.');}catch{toast('This is not a valid DP Studio backup. No changes made.');}}
window.addEventListener('hashchange',()=>{stop();step=0;lessonTab=route().page==='lesson'&&route.previous==='notes'?'notes':'learn';const r=route();if(r.page==='lesson'&&data.some(p=>p.id===r.id)){saved.last=r.id;persist()}route.previous=r.page;render();window.scrollTo(0,0)});
window.addEventListener('keydown',e=>{if(route().page==='flashcards'&&e.code==='Space'&&!/INPUT|TEXTAREA|SELECT|BUTTON/.test(document.activeElement.tagName)){e.preventDefault();flipped=!flipped;render()}});
route.previous=route().page;render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'open_dp_lesson',description:'Open a DP lesson in the learning workspace.',inputSchema:{type:'object',properties:{lessonId:{type:'integer'}},required:['lessonId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async({lessonId})=>{if(!Number.isInteger(lessonId)||!data.some(p=>p.id===lessonId))throw new Error('Unknown lesson');stop();step=0;lessonTab='learn';history.pushState(null,'',`#lesson/${lessonId}`);saved.last=lessonId;persist();render();return {lessonId,title:data.find(p=>p.id===lessonId).title}}})).catch(()=>{});}catch{}}

